  'export_go' => ['Prepare and download', 'تجهيز وتنزيل'], 'export_pw_short' => ['Use a password of 10 characters or more.', 'استعمل كلمة مرور من 10 أحرف أو أكثر.'], 'export_failed' => ['The export could not be prepared. Try again or contact support.', 'تعذّر تجهيز التصدير. أعد المحاولة أو تواصل مع الدعم.'],
